import { describe, it, expect } from "vitest";
import { quote, claim } from "./claim-office.js";

describe("Claim Office - Quote", () => {
  // Edge case: empty item list
  it.todo("empty item list -> premium 5 G (only processing fee)");

  // Base premiums for main items (base + 10% first insurance + 5 fee)
  it.todo("single sword (steel, ench 3) -> base 100 + 10 first + 5 fee = 115 G");
  it.todo("single amulet -> base 60 + 6 first + 5 fee = 71 G");
  it.todo("single staff -> base 80 + 8 first + 5 fee = 93 G");
  it.todo("single potion -> base 40 + 4 first + 5 fee = 49 G");

  // Component base premiums (block rule)
  it.todo("2 runes -> base 50 (+5 first +5 fee)");
  it.todo("3 runes -> base 60 (block applies)");
  it.todo("4 runes -> base 100 (no block, requires exactly 3)");
  it.todo("7 runes -> base 175");

  // "Alike" components
  it.todo("2 runes + 1 moonstone -> base 75 (no block: different types)");
  it.todo("3 runes + 3 moonstones -> base 120 (two separate blocks)");

  // Item-specific modifiers
  it.todo("cursed sword adds 50% surcharge on item base premium");
  it.todo("high-enchantment sword (ench >= 5) adds 30% surcharge");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed sword with exactly enchantment 5 -> both surcharges apply");

  // Modifier scope on multi-item policies
  it.todo("cursed sword + plain amulet -> curse adds 50% of sword base only");

  // Policy-wide modifiers
  it.todo("customer with exactly 2 years -> 20% loyalty discount applies");
  it.todo("follow-up contract (second quote) -> 15% discount");

  // Rounding
  it.todo("premium yielding 197.5 G -> 198 G (rounded up, MHPCO favor)");

  // Integration examples
  it.todo("newcomer with cursed sword (steel, ench 3) -> 165 G");
  it.todo("long-standing customer 2nd contract, cursed sword ench 7 -> 160 G");

  // Errors
  it.todo("unknown item type -> throws error");
});

describe("Claim Office - Claim", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, ench 3), damage 500 -> payout 400 (deductible)");
  it.todo("rune damage 200 -> payout 100 (deductible, no special clause)");

  // High enchantment clause
  it.todo("steel sword ench 9, damage 1000 -> payout 400 (50% then deductible)");

  // Dragon material clause
  it.todo("dragon-material sword ench 5, damage 800 -> payout 700 (full then deductible)");

  // Both clauses -> 50% wins
  it.todo("dragon sword ench 9, damage 1000 -> payout 400 (50% wins)");
  it.todo("dragon sword ench 8, damage 1000 -> payout 400 (high-ench applies)");

  // Deductible per damage event
  it.todo("dragon attack: sword 500 + amulet 300 -> payout 600 (deductible each)");

  // Cap
  it.todo("sword cap 2000; two claims 1500 each -> 1400 then 600, remaining 0");

  // Multiple items of same type
  it.todo("two swords -> insurance sum 2000, cap 4000; both damaged separately");
  it.todo("more damages of a type than insured -> rejected (throws)");

  // Cap based on unmodified insurance value
  it.todo("cursed sword premium modified -> cap still 2000 (unmodified value)");

  // Rounding payout
  it.todo("payout yielding 350.5 G -> 350 G (rounded down, MHPCO favor)");

  // Errors
  it.todo("claim references item not in policy -> throws");
  it.todo("claim with negative amount -> throws");
});

