input.newString:
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const componentBase = (count: number): number => {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const remainder = count % BLOCK_SIZE;
  return blocks * BLOCK_PREMIUM + remainder * COMPONENT_PREMIUM;
};

export const quote = (
  customer: unknown,
  items: { type: string }[],
  stepIndex: unknown,
): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  const mainBase = items
    .filter((item) => item.type !== "rune")
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const policyBase = mainBase + componentBase(runeCount);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const premiumBeforeFee = policyBase + firstInsuranceSurcharge;
  return premiumBeforeFee + PROCESSING_FEE;
};

