const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const componentBase = (count: number): number => {
  if (count === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return count * COMPONENT_PREMIUM;
};

const isComponent = (item: { type: string }): boolean => COMPONENT_TYPES.has(item.type);

const componentsBase = (items: { type: string }[]): number => {
  const countsByType = new Map<string, number>();
  for (const item of items.filter(isComponent)) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const count of countsByType.values()) {
    total += componentBase(count);
  }
  return total;
};

export const quote = (
  customer: unknown,
  items: { type: string }[],
  stepIndex: unknown,
): number => {
  const mainBase = items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const policyBase = mainBase + componentsBase(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const premiumBeforeFee = policyBase + firstInsuranceSurcharge;
  return premiumBeforeFee + PROCESSING_FEE;
};

