const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

const componentBase = (count: number): number => {
  if (count === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return count * COMPONENT_PREMIUM;
};

const isComponent = (item: { type: string }): boolean => COMPONENT_TYPES.has(item.type);

const componentsBase = (items: { type: string }[]): number => {
  const countsByType = new Map<string, number>();
  for (const item of items.filter(isComponent)) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const count of countsByType.values()) {
    total += componentBase(count);
  }
  return total;
};

const itemBase = (item: Item): number =>
  isComponent(item) ? COMPONENT_PREMIUM : BASE_PREMIUMS[item.type];

const itemSurcharges = (item: Item): number => {
  let surcharge = 0;
  if (item.cursed) {
    surcharge += itemBase(item) * CURSE_SURCHARGE_RATE;
  }
  return surcharge;
