export const quote = (
  customer: Customer,
  items: Item[],
  stepIndex: unknown,
): number => {
  const nonComponentBase = items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + itemBase(item), 0);
  const policyBase = nonComponentBase + componentsBase(items);
  const surcharges = items.reduce((sum, item) => sum + itemSurcharges(item), 0);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
  const premiumBeforeFee = policyBase + surcharges + firstInsuranceSurcharge - loyaltyDiscount;
  return premiumBeforeFee + PROCESSING_FEE;
};

