  const surcharges = items.reduce((sum, item) => sum + itemSurcharges(item), 0);
  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
  const followupDiscount = quoteIndex > 0 ? base * FOLLOWUP_DISCOUNT_RATE : 0;
  return (
    base + surcharges + firstInsuranceSurcharge - loyaltyDiscount(customer, base) - followupDiscount
  );
};

export const quote = (
  customer: Customer,
  items: Item[],
  quoteIndex: number,
): number => {
  return premiumBeforeFee(customer, items, quoteIndex) + PROCESSING_FEE;
};

