const DEDUCTIBLE = 100;
const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;

type Damage = {
  itemType: string;
  amount: number;
};

type Incident = {
  cause: string;
  damages: Damage[];
};

type ClaimResult = {
  payout: number;
  remainingCap: number;
};

const damagePayout = (damage: Damage, item: Item): number => {
  const highEnchantment =
    item.enchantment !== undefined && item.enchantment >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD;
  const reimbursed = highEnchantment
    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : damage.amount;
  return reimbursed - DEDUCTIBLE;
};

export const claim = (
  items: Item[],
  incident: Incident,
  remainingCap: number,
): ClaimResult => {
  const payout = incident.damages.reduce((sum, damage) => {
    const item = items.find((i) => i.type === damage.itemType)!;
    return sum + damagePayout(damage, item);
  }, 0);
  return { payout, remainingCap: remainingCap - payout };
};

