input.newString:
export const claim = (
  items: Item[],
  incident: Incident,
  remainingCap: number,
): ClaimResult => {
  const desiredPayout = incident.damages.reduce((sum, damage) => {
    const item = items.find((i) => i.type === damage.itemType)!;
    return sum + damagePayout(damage, item);
  }, 0);
  const payout = Math.min(desiredPayout, remainingCap);
  return { payout, remainingCap: remainingCap - payout };
};

