const validateDamages = (items: Item[], damages: Damage[]): void => {
  const insuredCounts = new Map<string, number>();
  for (const item of items) {
    insuredCounts.set(item.type, (insuredCounts.get(item.type) ?? 0) + 1);
  }
  const damageCounts = new Map<string, number>();
  for (const damage of damages) {
    damageCounts.set(damage.itemType, (damageCounts.get(damage.itemType) ?? 0) + 1);
  }
  for (const [type, count] of damageCounts) {
    if (count > (insuredCounts.get(type) ?? 0)) {
      throw new Error(`More damages of type ${type} than insured`);
    }
  }
};

export const claim = (
  items: Item[],
  incident: Incident,
  remainingCap: number,
): ClaimResult => {
  validateDamages(items, incident.damages);
  const desiredPayout = incident.damages.reduce(
    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
    0,
  );
  const payout = Math.min(desiredPayout, remainingCap);
  return { payout, remainingCap: remainingCap - payout };
};

